import static org.junit.Assert.assertNull;

/**
 * Unit tests for SubLine.intersection.
 */
public class SubLine_intersection_TriageGen3Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_BothInside_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (2,2)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        // Line 2: (0,2) to (2,0)
        SubLine sub2 = new SubLine(new Vector2D(0, 2), new Vector2D(2, 0));

        // Intersection is at (1,1) which is inside both
        Vector2D result = sub1.intersection(sub2, true);

        assertNotNull(result);
        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(1.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_BothInside_IncludeEndPointsFalse() {
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        SubLine sub2 = new SubLine(new Vector2D(0, 2), new Vector2D(2, 0));

        // Intersection is at (1,1) which is inside both
        Vector2D result = sub1.intersection(sub2, false);

        assertNotNull(result);
        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(1.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_AtEndpoint_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (2,2)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        // Line 2: (2,2) to (4,0)
        SubLine sub2 = new SubLine(new Vector2D(2, 2), new Vector2D(4, 0));

        // Intersection is at (2,2) which is an endpoint
        Vector2D result = sub1.intersection(sub2, true);

        assertNotNull(result);
        assertEquals(2.0, result.getX(), EPSILON);
        assertEquals(2.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_AtEndpoint_IncludeEndPointsFalse() {
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        SubLine sub2 = new SubLine(new Vector2D(2, 2), new Vector2D(4, 0));

        // Intersection is at (2,2) which is endpoint. 
        // includeEndPoints=false means we only accept Location.INSIDE (not boundary)
        Vector2D result = sub1.intersection(sub2, false);

        assertNull(result);
    }

    @Test
    public void testIntersection_OneOutside_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (2,2)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        // Line 2: (3,0) to (3,3) -> Intersection with Line 1 is at (3,3) but Line 1 ends at (2,2)
        // Wait, let's make the intersection point (3,3)
        // Line 1: (0,0) to (4,4)
        // Line 2: (0,6) to (6,0) -> intersection at (3,3)
        SubLine sub1_ext = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        SubLine sub2_ext = new SubLine(new Vector2D(0, 6), new Vector2D(6, 0));

        // Intersection of infinite lines is (3,3). 
        // (3,3) is OUTSIDE sub1 (0,0 to 2,2)
        Vector2D result = sub1_ext.intersection(sub2_ext, true);

        assertNull(result);
    }

    @Test
    public void testIntersection_OneOutside_IncludeEndPointsFalse() {
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        SubLine sub2 = new SubLine(new Vector2D(0, 6), new Vector2D(6, 0));

        // Intersection is (3,3), which is outside sub1
        Vector2D result = sub1.intersection(sub2, false);

        assertNull(result);
    }

    @Test
    public void testIntersection_BothOutside_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (1,1)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(1, 1));
        // Line 2: (0,2) to (2,0) -> intersection (1,1)
        SubLine sub2 = new SubLine(new Vector2D(0, 2), new Vector2D(2, 0));

        // Intersection at (1,1). This is an endpoint for sub1 and sub2.
        // If we shift sub2 so (1,1) is outside:
        SubLine sub2_outside = new SubLine(new Vector2D(0, 3), new Vector2D(3, 0));
        // Infinite lines: y=x and y=-x+3 -> 2x=3 -> x=1.5, y=1.5
        // (1.5, 1.5) is outside sub1 (0,0 to 1,1)

        Vector2D result = sub1.intersection(sub2_outside, true);
        assertNull(result);
    }
}
